-- composition of rule kernels statistics_propagation x window_self_join (duckdb), template graft_exists
WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT []::text[] AS c0, 100.0::float8 AS c1, '0'::interval AS c2 UNION ALL SELECT ARRAY['1'::text] AS c0, 100.0::float8 AS c1, MAX ('-1 month'::interval) OVER () AS c2 FROM (SELECT * FROM tp WHERE EXISTS (SELECT 1 FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT 100 AS c0, 16 AS c1 UNION SELECT 27 AS c0, 17 AS c1) AS kb) OR NOT EXISTS (SELECT 1 FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT 100 AS c0, 16 AS c1 UNION SELECT 27 AS c0, 17 AS c1) AS kb)) AS a1;
-- pgfuzz:check kernel:graft_exists WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT []::text[] AS c0, 100.0::float8 AS c1, '0'::interval AS c2 UNION ALL SELECT ARRAY['1'::text] AS c0, 100.0::float8 AS c1, MAX ('-1 month'::interval) OVER () AS c2 FROM tp AS a1
